using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Threading;
public static class V6Tests {
 static void Check(bool value,string reason){if(!value)throw new Exception(reason);}
 static void Until(Func<bool> condition,string reason,int timeout=10000){var watch=Stopwatch.StartNew();while(!condition()&&watch.ElapsedMilliseconds<timeout)Thread.Sleep(20);Check(condition(),reason);}
 static Server Device(string name){return new Server{Name=name,Host=name,User="test",Port=22};}
 static Metrics Data(int value){return new Metrics{Cpu=value+"%",Cores="4",Mem="512 / 1024 MiB",Disk="10% used / 100G free",CpuCores=new List<CpuCore>{new CpuCore{Index=0,Util=value}}};}
 public static int Run(string folder){folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);var log=new List<string>();var writer=new ArchiveService(30,1024,Path.Combine(folder,"independent"));var counts=new ConcurrentDictionary<string,int>();var active=new ConcurrentDictionary<string,int>();var maxActive=new ConcurrentDictionary<string,int>();var received=new ConcurrentBag<DeviceReading>();var blocked=new ManualResetEventSlim(false);Server fast=Device("fast"),slow=Device("slow"),flaky=Device("flaky");var start=DateTime.UtcNow.AddSeconds(-1);
 var capture=new DeviceCapture(writer,r=>received.Add(r),s=>{int concurrent=active.AddOrUpdate(s.Host,1,(k,v)=>v+1);maxActive.AddOrUpdate(s.Host,concurrent,(k,v)=>Math.Max(v,concurrent));try{int n=counts.AddOrUpdate(s.Host,1,(k,v)=>v+1);if(s.Host=="slow")blocked.Wait(10000);if(s.Host=="flaky"&&n==1)throw new IOException("simulated disconnected");return Data(n);}finally{active.AddOrUpdate(s.Host,0,(k,v)=>v-1);}},3);
 capture.Configure(new[]{fast,slow,flaky},2);Until(()=>counts.ContainsKey("slow")&&counts.GetOrAdd("fast",0)>=2&&counts.GetOrAdd("flaky",0)>=2,"fast and reconnecting endpoints poll while slow is blocked");Check(counts["slow"]==1,"slow job not overlapped");Check(received.Any(x=>x.Device.Host=="flaky"&&!string.IsNullOrEmpty(x.Metrics.Error))&&received.Any(x=>x.Device.Host=="flaky"&&string.IsNullOrEmpty(x.Metrics.Error)),"failed endpoint automatically retried");log.Add("SLOW_DEVICE_DOES_NOT_BLOCK_OTHER_DEVICES=True");log.Add("FAILURE_RECORD_AND_AUTOMATIC_RECONNECT=True");Check(capture.DeviceCount==3,"all saved endpoints enrolled");log.Add("ALL_CONFIGURED_DEVICES_POLLED_WITHOUT_VIEW_SELECTION=True");
 capture.Configure(new[]{fast,flaky},2);blocked.Set();Until(()=>capture.RunningCount==0,"running jobs finish after remove");Check(capture.Stop(),"capture stop");Check(writer.Flush(5000),"archive flush");writer.Dispose();var store=new ArchiveStore(writer.Store.Root);var end=DateTime.UtcNow.AddSeconds(1);Check(store.Query(fast,start,end,CancellationToken.None).Points.Count>=2,"fast records persisted");Check(store.Query(flaky,start,end,CancellationToken.None).Points.Count>=2,"flaky records persisted");Check(store.Query(slow,start,end,CancellationToken.None).Points.Count==0,"removed in-flight device should not append after removal");Check(maxActive.Values.All(x=>x<=1),"one request per endpoint");log.Add("NO_PER_DEVICE_OVERLAP=True");log.Add("REMOVED_DEVICE_STOPS_FUTURE_WRITES=True");log.Add("EVERY_DEVICE_ARCHIVED_TO_LOCAL_DISK=True");
 var editWriter=new ArchiveService(30,1024,Path.Combine(folder,"credentials"));var entered=new ManualResetEventSlim(false);var release=new ManualResetEventSlim(false);var edited=Device("edit");edited.KeyPath="old";var editStart=DateTime.UtcNow.AddSeconds(-1);var editor=new DeviceCapture(editWriter,null,s=>{if(s.KeyPath=="old"){entered.Set();release.Wait(5000);return Data(11);}return Data(88);});editor.Configure(new[]{edited},2);Check(entered.Wait(5000),"original credential job starts");var next=edited.Copy();next.KeyPath="new";editor.Configure(new[]{next},2);release.Set();Until(()=>editor.Latest(next)!=null&&editor.Latest(next).Metrics.Cpu=="88%","new credentials replace stale pending results");editor.Stop();editWriter.Dispose();var editData=editWriter.Store.Query(next,editStart,DateTime.UtcNow.AddSeconds(1),CancellationToken.None);Check(editData.Points.Count>=1&&editData.Points.All(x=>x.Cpu==88),"stale credentials are not archived");log.Add("CONFIGURATION_REPLACEMENT_IGNORES_OLD_CREDENTIAL_RESULTS=True");
 var exitWriter=new ArchiveService(30,1024,Path.Combine(folder,"shutdown"));var hasEntered=new ManualResetEventSlim(false);var finish=new ManualResetEventSlim(false);var stopDevice=Device("exit");var exitStart=DateTime.UtcNow.AddSeconds(-1);var closing=new DeviceCapture(exitWriter,null,s=>{hasEntered.Set();finish.Wait(5000);return Data(66);});closing.Configure(new[]{stopDevice},2);Check(hasEntered.Wait(5000),"shutdown in-flight job");var stopping=Task.Run(()=>closing.Stop());Thread.Sleep(100);Check(!stopping.IsCompleted,"stop waits for in-flight job");finish.Set();Check(stopping.Result,"shutdown job completed");exitWriter.Dispose();Check(exitWriter.Store.Query(stopDevice,exitStart,DateTime.UtcNow.AddSeconds(1),CancellationToken.None).Points.Count==1,"shutdown drains final write");log.Add("SHUTDOWN_DRAINS_INFLIGHT_COLLECTION_AND_ARCHIVE=True");File.WriteAllLines(Path.Combine(folder,"v6-results.txt"),log);Console.WriteLine(string.Join("\n",log));return 0;}
 public static void Runtime(Application app,string folder){folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);Storage.PathName=Path.Combine(folder,"settings.xml");ArchiveStore.DefaultRoot=Path.Combine(folder,"archives");var remote=Storage.DefaultServer();var local=Storage.LocalServer();var options=new Settings{Interval=2,SelectedName=local.Name};options.Servers.Add(remote);options.Servers.Add(local);Storage.Save(options);var window=new MonitorWindow(false){ShowActivated=false,ShowInTaskbar=false,WindowStartupLocation=WindowStartupLocation.Manual,Left=-18000,Top=-18000};app.MainWindow=window;window.Show();var begin=DateTime.UtcNow.AddSeconds(-1);var watch=Stopwatch.StartNew();var log=new List<string>();int phase=0,remoteBaseline=0,localBaseline=0;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(350)};
 timer.Tick+=(a,b)=>{try{if(watch.Elapsed.TotalSeconds>65)throw new Exception("native continuous archive timeout phase="+phase);var r=window.ArchiveRepository.Query(remote,begin,DateTime.UtcNow.AddSeconds(1),CancellationToken.None);var l=window.ArchiveRepository.Query(local,begin,DateTime.UtcNow.AddSeconds(1),CancellationToken.None);if(phase==0&&r.Points.Count>=3&&l.Points.Count>=3){Check(((Server)window.ServerPicker.SelectedItem).IsLocal,"only local selected initially");Check(r.Points.All(x=>string.IsNullOrEmpty(x.Error))&&l.Points.All(x=>string.IsNullOrEmpty(x.Error)),"native endpoints connected");log.Add("REMOTE_NEVER_SELECTED_BUT_ARCHIVED="+r.Points.Count);log.Add("LOCAL_ARCHIVED_SIMULTANEOUSLY="+l.Points.Count);Check(window.BackgroundDeviceCount==2,"background enrolled endpoints");remoteBaseline=r.Points.Count;localBaseline=l.Points.Count;window.ChooseServer(remote);window.HideToTray();phase=1;}
 else if(phase==1&&r.Points.Count>=remoteBaseline+2&&l.Points.Count>=localBaseline+2){Check(!window.IsVisible&&window.TrayVisible,"tray background running");log.Add("TRAY_REMOTE_COUNT="+r.Points.Count);log.Add("TRAY_UNSELECTED_LOCAL_COUNT="+l.Points.Count);log.Add("BOTH_DEVICES_CONTINUE_IN_TRAY=True");window.Restore();window.SwitchView("历史");window.ArchiveView.SetRange(begin,DateTime.UtcNow.AddSeconds(1),true);phase=2;}
 else if(phase==2&&!window.ArchiveView.Loading){Check(window.ArchiveView.CurrentResult!=null&&window.ArchiveView.CurrentResult.Points.Count>=5,"remote historic disk read");log.Add("SELECTING_HISTORY_READS_ALREADY_ARCHIVED_RECORDS=True");window.RenderImage(Path.Combine(folder,"remote-continuous-history-live.png"),(int)Math.Ceiling(window.Root.ActualWidth+48),(int)Math.Ceiling(window.Root.ActualHeight+48),120);window.ChooseServer(local);window.SwitchView("历史");window.ArchiveView.SetRange(begin,DateTime.UtcNow.AddSeconds(1),true);phase=3;}
 else if(phase==3&&!window.ArchiveView.Loading){Check(window.ArchiveView.CurrentResult!=null&&window.ArchiveView.CurrentResult.Points.Count>=5,"local historic disk read");window.RenderImage(Path.Combine(folder,"local-continuous-history-live.png"),(int)Math.Ceiling(window.Root.ActualWidth+48),(int)Math.Ceiling(window.Root.ActualHeight+48),120);log.Add(window.NativeReview());log.Add("STARTUP_NOT_MODIFIED=True");timer.Stop();window.Exit();var disk=new ArchiveStore(ArchiveStore.DefaultRoot);var rr=disk.Query(remote,begin,DateTime.UtcNow.AddSeconds(1),CancellationToken.None);var ll=disk.Query(local,begin,DateTime.UtcNow.AddSeconds(1),CancellationToken.None);Check(rr.Points.Count>=5&&ll.Points.Count>=5,"both disks reopened after app exit");log.Add("POST_EXIT_REMOTE_RECORDS="+rr.Points.Count);log.Add("POST_EXIT_LOCAL_RECORDS="+ll.Points.Count);log.Add("CROSS_DEVICE_ARCHIVES_ON_LOCAL_DISK=True");File.WriteAllLines(Path.Combine(folder,"runtime-results.txt"),log);}}
 catch(Exception error){timer.Stop();File.WriteAllText(Path.Combine(folder,"runtime-error.txt"),error.ToString());window.Exit();}};timer.Start();}
}
